import adminContext from "./adminContext";
import { useState } from 'react'

const StudentState = (props) => {
  const host = "https://66a85624fdcd54c7d19bfcb6--dining-hall-management.netlify.app/server";
  const adminInitial = []
  const [admin, setAdmin] = useState(adminInitial)

  //get all notes
  const getDetailsAdmin = async () => {

    // api calls
    const response = await fetch(`${host}/api/auth/getadmin`, {
      method: 'GET',
      headers: {
        'Content-Type': 'application/json',
        "auth-token": localStorage.getItem('token')
      },
    });
    const json = await response.json()
    //  console.log(json)
    setAdmin(json)

  }
  return (
    <>
      <adminContext.Provider value={{ admin, getDetailsAdmin }}>
        {props.children}
      </adminContext.Provider>
    </>
  )
}

export default StudentState